cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#define LN_BLOCK 256
#define CHUNKS_PER_ROW 64
// Phase 1: each (row, chunk) block computes a partial sum / sum-of-squares
// over a strided slice of the row and atomically accumulates it into
// global per-row accumulators. This spreads the reduction work for each
// row across many CTAs, greatly increasing the number of blocks launched
// (N * CHUNKS_PER_ROW instead of just N) and improving SM occupancy for
// the large-M / small-N shapes used by this LayerNorm.
__global__ __launch_bounds__(LN_BLOCK, 8) void cute_layernorm_reduce_kernel(
    float const* __restrict__ X,
    int N, int M, int chunks_per_row,
    float* __restrict__ sum_buf,
    float* __restrict__ sqsum_buf)
{
    int row = blockIdx.x / chunks_per_row;
    int chunk_id = blockIdx.x % chunks_per_row;
    if (row >= N) return;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int total_threads_per_row = chunks_per_row * nthreads;
    int global_tid = chunk_id * nthreads + tid;
    float const* xn = X + (size_t)row * M;
    int M4 = M / 4;
    float4 const* xn4 = reinterpret_cast<float4 const*>(xn);
    float local_sum = 0.f;
    float local_sqsum = 0.f;
    {
        int stride = total_threads_per_row;
        int i = global_tid;
        for (; i + 3 * stride < M4; i += 4 * stride) {
            float4 v0 = __ldg(&xn4[i]);
            float4 v1 = __ldg(&xn4[i + stride]);
            float4 v2 = __ldg(&xn4[i + 2 * stride]);
            float4 v3 = __ldg(&xn4[i + 3 * stride]);
            local_sum += v0.x + v0.y + v0.z + v0.w;
            local_sum += v1.x + v1.y + v1.z + v1.w;
            local_sum += v2.x + v2.y + v2.z + v2.w;
            local_sum += v3.x + v3.y + v3.z + v3.w;
            local_sqsum += v0.x * v0.x + v0.y * v0.y + v0.z * v0.z + v0.w * v0.w;
            local_sqsum += v1.x * v1.x + v1.y * v1.y + v1.z * v1.z + v1.w * v1.w;
            local_sqsum += v2.x * v2.x + v2.y * v2.y + v2.z * v2.z + v2.w * v2.w;
            local_sqsum += v3.x * v3.x + v3.y * v3.y + v3.z * v3.z + v3.w * v3.w;
        }
        for (; i < M4; i += stride) {
            float4 v4 = __ldg(&xn4[i]);
            local_sum += v4.x + v4.y + v4.z + v4.w;
            local_sqsum += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
        }
    }
    if (chunk_id == 0) {
        for (int i = M4 * 4 + tid; i < M; i += nthreads) {
            float v = __ldg(&xn[i]);
            local_sum += v;
            local_sqsum += v * v;
        }
    }
    for (int offset = 16; offset > 0; offset >>= 1) {
        local_sum += __shfl_down_sync(0xffffffff, local_sum, offset);
        local_sqsum += __shfl_down_sync(0xffffffff, local_sqsum, offset);
    }
    __shared__ float warp_sum[LN_BLOCK / 32];
    __shared__ float warp_sqsum[LN_BLOCK / 32];
    int warp_id = tid / 32;
    int lane_id = tid % 32;
    if (lane_id == 0) {
        warp_sum[warp_id] = local_sum;
        warp_sqsum[warp_id] = local_sqsum;
    }
    __syncthreads();
    int num_warps = (nthreads + 31) / 32;
    if (warp_id == 0) {
        float s = (lane_id < num_warps) ? warp_sum[lane_id] : 0.f;
        float sq = (lane_id < num_warps) ? warp_sqsum[lane_id] : 0.f;
        for (int offset = 16; offset > 0; offset >>= 1) {
            s += __shfl_down_sync(0xffffffff, s, offset);
            sq += __shfl_down_sync(0xffffffff, sq, offset);
        }
        if (lane_id == 0) {
            // Accumulate directly into the per-row sum/sqsum buffers with a
            // single atomicAdd per block instead of writing to a separate
            // partial buffer that a follow-up finalize kernel must reduce.
            // Only chunks_per_row blocks contend per row, so atomic
            // contention is negligible, while this eliminates an entire
            // kernel launch and the extra global memory round-trip for the
            // partial-sum arrays.
            atomicAdd(&sum_buf[row], s);
            atomicAdd(&sqsum_buf[row], sq);
        }
    }
}
// Phase 2: each (row, chunk) block re-derives mean/invstd from the fully
// reduced per-row accumulators and normalizes its strided slice of the
// row. Splitting the normalization across CHUNKS_PER_ROW blocks per row
// (instead of a single block per row) again increases the number of
// concurrently schedulable blocks for better occupancy.
__global__ __launch_bounds__(LN_BLOCK, 8) void cute_layernorm_normalize_kernel(
    float const* __restrict__ X,
    float const* __restrict__ W,
    float const* __restrict__ B,
    float* __restrict__ Y,
    int N, int M, int chunks_per_row, float eps,
    float const* __restrict__ sum_buf,
    float const* __restrict__ sqsum_buf)
{
    int row = blockIdx.x / chunks_per_row;
    int chunk_id = blockIdx.x % chunks_per_row;
    if (row >= N) return;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int total_threads_per_row = chunks_per_row * nthreads;
    int global_tid = chunk_id * nthreads + tid;
    float mean = sum_buf[row] / (float)M;
    float var = sqsum_buf[row] / (float)M - mean * mean;
    if (var < 0.f) var = 0.f;
    float invstd = rsqrtf(var + eps);
    float const* xn = X + (size_t)row * M;
    float* yn = Y + (size_t)row * M;
    int M4 = M / 4;
    float4 const* xn4 = reinterpret_cast<float4 const*>(xn);
    float4 const* wn4 = reinterpret_cast<float4 const*>(W);
    float4 const* bn4 = reinterpret_cast<float4 const*>(B);
    float4* yn4 = reinterpret_cast<float4*>(yn);
    {
        int stride = total_threads_per_row;
        int i = global_tid;
        for (; i + 3 * stride < M4; i += 4 * stride) {
            float4 v0 = __ldg(&xn4[i]);
            float4 w0 = __ldg(&wn4[i]);
            float4 b0 = __ldg(&bn4[i]);
            float4 v1 = __ldg(&xn4[i + stride]);
            float4 w1 = __ldg(&wn4[i + stride]);
            float4 b1 = __ldg(&bn4[i + stride]);
            float4 v2 = __ldg(&xn4[i + 2 * stride]);
            float4 w2 = __ldg(&wn4[i + 2 * stride]);
            float4 b2 = __ldg(&bn4[i + 2 * stride]);
            float4 v3 = __ldg(&xn4[i + 3 * stride]);
            float4 w3 = __ldg(&wn4[i + 3 * stride]);
            float4 b3 = __ldg(&bn4[i + 3 * stride]);
            float4 out0, out1, out2, out3;
            out0.x = (v0.x - mean) * invstd * w0.x + b0.x;
            out0.y = (v0.y - mean) * invstd * w0.y + b0.y;
            out0.z = (v0.z - mean) * invstd * w0.z + b0.z;
            out0.w = (v0.w - mean) * invstd * w0.w + b0.w;
            out1.x = (v1.x - mean) * invstd * w1.x + b1.x;
            out1.y = (v1.y - mean) * invstd * w1.y + b1.y;
            out1.z = (v1.z - mean) * invstd * w1.z + b1.z;
            out1.w = (v1.w - mean) * invstd * w1.w + b1.w;
            out2.x = (v2.x - mean) * invstd * w2.x + b2.x;
            out2.y = (v2.y - mean) * invstd * w2.y + b2.y;
            out2.z = (v2.z - mean) * invstd * w2.z + b2.z;
            out2.w = (v2.w - mean) * invstd * w2.w + b2.w;
            out3.x = (v3.x - mean) * invstd * w3.x + b3.x;
            out3.y = (v3.y - mean) * invstd * w3.y + b3.y;
            out3.z = (v3.z - mean) * invstd * w3.z + b3.z;
            out3.w = (v3.w - mean) * invstd * w3.w + b3.w;
            yn4[i] = out0;
            yn4[i + stride] = out1;
            yn4[i + 2 * stride] = out2;
            yn4[i + 3 * stride] = out3;
        }
        for (; i < M4; i += stride) {
            float4 v4 = __ldg(&xn4[i]);
            float4 w4 = __ldg(&wn4[i]);
            float4 b4 = __ldg(&bn4[i]);
            float4 out;
            out.x = (v4.x - mean) * invstd * w4.x + b4.x;
            out.y = (v4.y - mean) * invstd * w4.y + b4.y;
            out.z = (v4.z - mean) * invstd * w4.z + b4.z;
            out.w = (v4.w - mean) * invstd * w4.w + b4.w;
            yn4[i] = out;
        }
    }
    if (chunk_id == 0) {
        for (int i = M4 * 4 + tid; i < M; i += nthreads) {
            float v = __ldg(&xn[i]);
            float w = __ldg(&W[i]);
            float b = __ldg(&B[i]);
            float norm = (v - mean) * invstd;
            yn[i] = norm * w + b;
        }
    }
}
torch::Tensor cute_layernorm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
