    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(bias.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == torch::kFloat32, "bias must be float32");
    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();
    int64_t total_numel = x_c.numel();
    int64_t norm_numel = w_c.numel();
    TORCH_CHECK(total_numel % norm_numel == 0, "shape mismatch");
    int N = (int)(total_numel / norm_numel);
    int M = (int)norm_numel;
    auto y = torch::empty_like(x_c);
    // sum_buf / sqsum_buf are accumulated directly via atomicAdd inside the
    // reduce kernel, so we no longer need per-(row,chunk) partial buffers
    // nor a separate finalize kernel to reduce them. This removes an
    // entire kernel launch and the extra global memory traffic that would
    // otherwise be spent writing and re-reading the partial sums.
    auto sum_buf = torch::zeros({N}, x_c.options());
    auto sqsum_buf = torch::zeros({N}, x_c.options());
    dim3 grid(N * CHUNKS_PER_ROW);
    dim3 block(LN_BLOCK);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    cute_layernorm_reduce_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        N, M, CHUNKS_PER_ROW,
        sum_buf.data_ptr<float>(),
        sqsum_buf.data_ptr<float>());
    cute_layernorm_normalize_kernel<<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N, M, CHUNKS_PER_ROW, (float)eps,
        sum_buf.data_ptr<float>(),
        sqsum_buf.data_ptr<float>());
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE layernorm launch failed");
    return y;
}
"""
cute_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_layernorm"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs Layer Normalization using a custom CUTE kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = normalized_shape
        self.weight = nn.Parameter(torch.ones(normalized_shape))
        self.bias = nn.Parameter(torch.zeros(normalized_shape))
        self.eps = 1e-5
        self._ext = cute_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_layernorm(x, self.weight, self.bias, self.eps)

